fn release_inventory_evidence_inert_gh_deadline_reaps_owned_descendant() {
    let fixture = Fixture::new(OWNED_WAIT);
    let start = Instant::now();
    let mut owned = fixture.owned(Duration::from_secs(1));
    assert!(
        owned
            .request(&["release", "view"])
            .err()
